// This script body runs in the user's bot host (Claude Custom Action sandbox).
// It assumes `@seele/memory-client` is installed in the project root.

import {
  hashEmbedder384,
  sealWithContentKey,
  openWithContentKey,
  base64ToBytes,
} from '@seele/memory-client'

// 1. Read secrets from the runtime environment.
const baseUrl = process.env.SEELE_BASE_URL || 'https://seele-memory.griptoad.workers.dev'
const botJwt = process.env.SEELE_BOT_JWT
const aesKeyB64 = process.env.SEELE_AES_KEY_B64
if (!botJwt) throw new Error('SEELE_BOT_JWT is required (mint via POST /api/bots)')
if (!aesKeyB64) throw new Error('SEELE_AES_KEY_B64 is required (derive from your 12-word phrase)')

const aesKey = base64ToBytes(aesKeyB64)

// 2. Embed the query on-device. The plaintext leaves the host only as a vector.
const vec = await hashEmbedder384(inputs.query)
const query_vector = Array.from(vec) // Float32Array → number[] for JSON

// 3. Recall: bot JWT in Authorization header, query_vector in body, no plaintext query.
const resp = await fetch(`${baseUrl}/mem/v1/recall`, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    authorization: `Bearer ${botJwt}`,
  },
  body: JSON.stringify({
    query_vector,
    top_k: inputs.top_k || 5,
  }),
})
if (!resp.ok) {
  const err = await resp.json().catch(() => ({}))
  throw new Error(`recall failed: ${resp.status} ${err.error || ''} ${err.message || ''}`)
}
const { snippets, query_id } = await resp.json()

// 4. Decrypt each snippet locally. Server cannot open these — only we have the key.
const decrypted = await Promise.all(
  snippets.map(async (s) => {
    const ciphertext = base64ToBytes(s.body_encrypted)
    const plaintext = await openWithContentKey(aesKey, ciphertext)
    return {
      chunk_id: s.chunk_id,
      score: s.score,
      created_at: s.created_at,
      text: new TextDecoder().decode(plaintext),
    }
  }),
)

return { snippets: decrypted, query_id }
